// Some portions generated by Codex
package org.eclipse.rdf4j.workbench.security;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;

class WorkbenchFrontendSecurityTest {

	@Test
	void browserNeverReadsCredentialsOrWritesUntrustedHtml() throws Exception {
		String server = source("server.ts");
		String template = source("template.ts");
		String savedQueries = source("saved-queries.ts");

		assertThat(server).doesNotContain("btoa", "server-user-password");
		assertThat(template).doesNotContain("server-user-password", "atob", "innerHTML");
		assertThat(savedQueries).doesNotContain("server-user-password", "atob", "innerHTML");
	}

	@Test
	void stylesheetsRenderServerUserAndCsrfAsEscapedData() throws Exception {
		String server = Files.readString(Path.of("src/main/webapp/transformations/server.xsl"));
		String template = Files.readString(Path.of("src/main/webapp/transformations/template.xsl"));

		assertThat(server).doesNotContain("onsubmit=")
				.contains("name=\"csrf-token\"")
				.contains("binding[@name='csrf-token']");
		assertThat(template).contains("binding[@name='authenticated-user']")
				.contains("<xsl:value-of")
				.doesNotContain("<td id=\"selected-user\"></td>");
	}

	private static String source(String name) throws Exception {
		return Files.readString(Path.of("src/main/webapp/scripts/ts", name));
	}
}
